begin;

update public.noticias set traducoes = traducoes || $json${"en-US": {"titulo": "TALENTOS DO IDEX FESTIVAL BRINGS TOGETHER MORE THAN 500 YOUNG PEOPLE IN SÃO PAULO'S EAST SIDE", "resumo": "This project reinforced the role of sport as a tool for inclusion and social development.", "conteudo": "From April 13 to 17, 2026, Instituto IDEX held the Talentos do IDEX Festival at Esporte Clube Owens Illinois, in Ermelino Matarazzo.\nThere were three major sports gatherings, bringing together 513 direct participants and more than 2,000 indirect beneficiaries.\nThe competitions included U-12, U-14 and U-16 categories, with nine teams per event."}, "es-ES": {"titulo": "EL FESTIVAL TALENTOS DO IDEX REÚNE A MÁS DE 500 JÓVENES EN LA ZONA ESTE DE SÃO PAULO", "resumo": "Esta iniciativa reforzó el papel del deporte como herramienta de inclusión y desarrollo social.", "conteudo": "Del 13 al 17 de abril de 2026, el Instituto IDEX organizó el Festival Talentos do IDEX en el Esporte Clube Owens Illinois, en Ermelino Matarazzo.\nFueron tres grandes encuentros deportivos, que reunieron a 513 participantes directos y a más de 2.000 beneficiarios indirectos.\nLas competiciones abarcaron las categorías Sub-12, Sub-14 y Sub-16, con nueve equipos por evento."}}$json$::jsonb
where slug = 'festival-talentos-do-idex-mobiliza-mais-de-500-jovens-na-zona-leste-paulista';

update public.noticias set traducoes = traducoes || $json${"en-US": {"titulo": "TALENTO BRASIL PROJECT TRAINS 300 YOUNG PEOPLE IN GREATER SÃO PAULO", "resumo": "The Talento Brasil project reaffirms IDEX's commitment to structured, long-term development.", "conteudo": "The Talento Brasil Project is underway, providing ongoing soccer training to 300 teenagers and young people from public schools.\nActivities take place at the Parelheiros and Ferraz de Vasconcelos hubs, three times a week, in U-13, U-15 and U-17 groups.\nBeyond technical and physical development, the project works on values such as citizenship, discipline and social interaction. Supervisors, coaches and trainers follow each participant, ensuring both athletic and personal growth."}, "es-ES": {"titulo": "EL PROYECTO TALENTO BRASIL FORMA A 300 JÓVENES DEL GRAN SÃO PAULO", "resumo": "El proyecto Talento Brasil reafirma el compromiso del IDEX con una formación estructurada y a largo plazo.", "conteudo": "El Proyecto Talento Brasil está en marcha y ofrece formación deportiva continuada en fútbol a 300 adolescentes y jóvenes de la red pública de enseñanza.\nLas actividades se desarrollan en los polos de Parelheiros y Ferraz de Vasconcelos, tres veces por semana, en grupos Sub-13, Sub-15 y Sub-17.\nAdemás del desarrollo técnico y físico, el proyecto trabaja valores de ciudadanía, disciplina y convivencia social. Supervisores, entrenadores y preparadores acompañan a cada participante, garantizando su evolución deportiva y personal."}}$json$::jsonb
where slug = 'projeto-talento-brasil-forma-300-jovens-da-grande-sao-paulo';

update public.noticias set traducoes = traducoes || $json${"en-US": {"titulo": "DRAFT DAY EVENT WILL BRING TOGETHER YOUNG SOCCER TALENT IN SÃO PAULO", "resumo": "This project is becoming a benchmark for social inclusion, athletic development and strengthening youth soccer.", "conteudo": "On November 12, 2026, IDEX will hold the 2nd Draft Day Event at Clube Esportivo da Penha, bringing together teenagers aged 11 to 16 from the Institute's four sports hubs.\n\nThere will be six official matches in the U-14 and U-16 categories, with technical and educational evaluation of the athletes.\n\nThe project will directly benefit 120 young people, promoting integration between hubs and recognizing standouts for their performance and conduct."}, "es-ES": {"titulo": "EL EVENTO DRAFT DAY REUNIRÁ A JÓVENES TALENTOS DEL FÚTBOL EN LA CAPITAL PAULISTA", "resumo": "Esta iniciativa se consolida como referente en inclusión social, formación deportiva y fortalecimiento del fútbol base.", "conteudo": "El 12 de noviembre de 2026, el IDEX celebrará el 2.º Evento Draft Day en el Clube Esportivo da Penha, que reunirá a adolescentes de 11 a 16 años de los cuatro polos deportivos del Instituto.\n\nSe disputarán seis partidos oficiales en las categorías Sub-14 y Sub-16, con evaluación técnica y pedagógica de los deportistas.\n\nEl proyecto beneficiará directamente a 120 jóvenes, fomentando la integración entre polos y premiando a quienes destaquen por su rendimiento y comportamiento."}}$json$::jsonb
where slug = 'evento-draft-day-reunira-jovens-talentos-do-futebol-na-capital-paulista';

update public.noticias set traducoes = traducoes || $json${"en-US": {"titulo": "PROJECTS DEVELOPED IN MUNICIPALITIES ACROSS SÃO PAULO STATE", "resumo": "A youth sports development project reaches young people in Parelheiros, in the South Zone of São Paulo, and in the city of Santa Gertrudes", "conteudo": "In 2025, IDEX set up two sports development hubs in Parelheiros (São Paulo) and Santa Gertrudes, directly serving 300 teenagers and young people aged 11 to 17.\n\nActivities took place three times a week, in U-13, U-15 and U-17 groups, with specialized technical supervision. The project worked on soccer fundamentals, physical skills and values such as ethics, discipline and citizenship.\n\nThe initiative expanded IDEX's institutional presence and strengthened its local work in youth development."}, "es-ES": {"titulo": "DESARROLLO DE PROYECTOS EN MUNICIPIOS DEL ESTADO DE SÃO PAULO", "resumo": "Una iniciativa de formación deportiva llega a jóvenes de Parelheiros, en la Zona Sur de la capital paulista, y de la ciudad de Santa Gertrudes", "conteudo": "En 2025, el IDEX puso en marcha dos polos de formación deportiva en Parelheiros (São Paulo) y Santa Gertrudes, atendiendo directamente a 300 adolescentes y jóvenes de entre 11 y 17 años.\n\nLas actividades se realizaron tres veces por semana, en grupos Sub-13, Sub-15 y Sub-17, con seguimiento técnico especializado. El proyecto trabajó los fundamentos del fútbol, las capacidades físicas y valores como la ética, la disciplina y la ciudadanía.\n\nLa iniciativa amplió la presencia institucional del IDEX y consolidó su actuación territorial en la formación de base."}}$json$::jsonb
where slug = 'desenvolvimento-de-projetos-em-municipios-paulistas';

update public.noticias set traducoes = traducoes || $json${"en-US": {"titulo": "1ST IDEX BRASIL DRAFT DAY EVENT A SUCCESS IN 2025", "resumo": "The first Draft Day brought together 120 young athletes in São Paulo and was a success!", "conteudo": "On August 16, 2025, IDEX held the 1st Draft Day Event at Clube Esportivo da Penha, bringing together 120 teenagers from the Institute's four sports hubs.\n\nTwelve official matches were played in the U-14 and U-16 categories, with technical evaluation and individual follow-up for each athlete.\n\nThe event fostered integration between hubs, healthy competition and close observation of the young players' performance.\n\nThis edition established Draft Day as IDEX's own initiative dedicated to strengthening youth soccer and recognizing talent."}, "es-ES": {"titulo": "EL 1.er EVENTO DRAFT DAY IDEX BRASIL, TODO UN ÉXITO EN 2025", "resumo": "¡El primer Draft Day reunió a 120 jóvenes deportistas en São Paulo y fue un éxito!", "conteudo": "El 16 de agosto de 2025, el IDEX organizó el 1.er Evento Draft Day en el Clube Esportivo da Penha, que reunió a 120 adolescentes de los cuatro polos deportivos del Instituto.\n\nSe disputaron 12 partidos oficiales en las categorías Sub-14 y Sub-16, con evaluación técnica y seguimiento individual de los deportistas.\n\nEl evento favoreció la integración entre polos, la competición sana y la observación detallada del rendimiento de los jóvenes.\n\nEsta edición consolidó el Draft Day como acción propia del IDEX dedicada al fortalecimiento del fútbol base y a la valoración del talento."}}$json$::jsonb
where slug = '1-evento-draft-day-idex-brasil-realizado-com-sucesso-em-2025';

update public.projetos set traducoes = traducoes || $json${"en-US": {"titulo": "Talento Brasil", "resumo": "Free soccer for 200 children and young people in youth categories.", "descricao": "Free soccer training for 200 children and young people in youth categories, in partnership with Clube Esportivo Penha. Launched on 06/26/2017 at the Santa Cruz do Rio Pardo City Council."}, "es-ES": {"titulo": "Talento Brasil", "resumo": "Fútbol gratuito para 200 niños y jóvenes de las categorías base.", "descricao": "Entrenamiento de fútbol gratuito para 200 niños y jóvenes de las categorías base, en colaboración con el Clube Esportivo Penha. Presentado el 26/06/2017 en la Cámara de Concejales de Santa Cruz do Rio Pardo."}}$json$::jsonb
where slug = 'talento-brasil';

